'use client'
import { ChevronLeft, ChevronRight } from 'lucide-react'
import { Button } from '@/react/components/ui/Button'
import { useControllable } from '@/react/hooks/useControllable'
import { cn } from '@/react/lib/cn'

// Pages of a long list, when its order means a place to come back to (an audit log): two secondary icon buttons
// around the page count in tabular figures, 12px muted. The buttons go grey at either end. Prefer ShowMore for a
// list read from the top (credits added, matches): it keeps what was read on screen. The page is `page` /
// `defaultPage` / `onPageChange` (Vue's v-model:page).
export interface PaginationProps {
  page?: number
  defaultPage?: number
  onPageChange?: (page: number) => void
  pages: number
  label?: string
  className?: string
}

export function Pagination({ page: given, defaultPage = 1, onPageChange, pages, label = 'pages', className }: PaginationProps) {
  const [page, setPage] = useControllable(given, defaultPage, onPageChange)
  return (
    <nav data-ds="pagination" className={cn('flex items-center gap-3', className)} aria-label={label}>
      <Button icon aria-label="Previous page" disabled={page <= 1} onClick={() => setPage(Math.max(1, page - 1))}><ChevronLeft size={14} strokeWidth={1.5} aria-hidden="true" /></Button>
      <span className="type-meta text-fg-muted tabular-nums" aria-live="polite">Page <span className="text-fg">{page}</span>{` of ${pages}`}</span>
      <Button icon aria-label="Next page" disabled={page >= pages} onClick={() => setPage(Math.min(pages, page + 1))}><ChevronRight size={14} strokeWidth={1.5} aria-hidden="true" /></Button>
    </nav>
  )
}

export default Pagination

import type { ButtonHTMLAttributes } from 'react'
import { cn } from '@/react/lib/cn'

// The quiet "Show 5 more" under a list (console2.css .v2-more): 12px medium in the soft ink that darkens under the
// pointer, a red focus ring, and a hit area 12px past its words. A list that can grow for years opens a few at a time
// with it, rather than paging.
export interface ShowMoreProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  count?: number
  label?: string
}

export function ShowMore({ count = 5, label, className, children, ...rest }: ShowMoreProps) {
  return (
    <>
      <style href="ds-show-more" precedence="ds">{css}</style>
      <button data-ds="show-more" type="button" className={cn('ds-more relative ml-1 cursor-pointer text-meta font-medium whitespace-nowrap text-fg-soft', className)} {...rest}>{children ?? label ?? `Show ${count} more`}</button>
    </>
  )
}

export default ShowMore

const css = `
.ds-more { transition: color var(--ds-duration-micro) var(--ds-easing-standard); }
.ds-more::after { position: absolute; inset: -12px; content: ""; }
@media (hover: hover) and (pointer: fine) { .ds-more:hover { color: var(--ds-color-fg); } }
.ds-more:focus-visible { outline: var(--ds-border-focus) solid var(--ds-color-edge-accent); outline-offset: var(--ds-border-focus); }
`

'use client'
import { useCallback, useRef, useState } from 'react'

// Vue's defineModel in React: a value that is controlled when the caller passes it (value + onValueChange, as Radix
// does) and kept inside otherwise (defaultValue). setValue calls onChange either way.
export function useControllable<T>(value: T | undefined, defaultValue: T, onChange?: (value: T) => void) {
	const [inner, setInner] = useState<T>(defaultValue)
	const controlled = value !== undefined
	const current = controlled ? value : inner
	const ref = useRef(onChange)
	ref.current = onChange
	const set = useCallback((next: T) => {
		if (!controlled) setInner(next)
		ref.current?.(next)
	}, [controlled])
	return [current, set] as const
}

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

