import { html } from 'lit/static-html.js'
import { ChevronLeft, ChevronRight } from 'lucide'
import { DsElement, define, tag } from '@/elements/lib/element'
import { icon } from '@/elements/lib/icon'
import '@/elements/components/ui/button'
import styles from 'virtual:tw'

// Pagination.vue as <conare-pagination>: pages of a long list, when its order means a place to come back to (an audit
// log): two secondary icon buttons around the page count in tabular figures, 12px muted. The buttons go grey at either
// end. Prefer <conare-show-more> for a list read from the top: it keeps what was read on screen. v-model:page is `page`
// with `page-change`.

/**
 * @summary Previous and next around the page count.
 * @fires page-change - The page changed (detail.value; read `page`).
 */
export class Pagination extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { page: { type: Number }, pages: { type: Number }, label: {} }

	/** The page shown, from 1. */
	page = 1
	/** How many pages. */
	pages = 1
	/** The nav's name. */
	label = 'pages'

	render() {
		const button = tag('button')
		return html`<nav class="contents" aria-label=${this.label}>
			<${button} icon aria-label="Previous page" ?disabled=${this.page <= 1} @click=${() => this.commit(Math.max(1, this.page - 1), 'page')}>${icon(ChevronLeft, 'chevron-left', { size: 14, strokeWidth: 1.5, attrs: { 'aria-hidden': 'true' } })}</${button}>
			<span class="type-meta text-fg-muted tabular-nums" aria-live="polite">Page <span class="text-fg">${this.page}</span>${` of ${this.pages}`}</span>
			<${button} icon aria-label="Next page" ?disabled=${this.page >= this.pages} @click=${() => this.commit(Math.min(this.pages, this.page + 1), 'page')}>${icon(ChevronRight, 'chevron-right', { size: 14, strokeWidth: 1.5, attrs: { 'aria-hidden': 'true' } })}</${button}>
		</nav>`
	}
}

define('pagination', Pagination)

import { html } from 'lit'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// ShowMore.vue as <conare-show-more>: the quiet "Show 5 more" under a list (console2.css .v2-more): 12px medium in the
// soft ink that darkens under the pointer, a red focus ring, and a hit area 12px past its words. A list that can grow
// for years opens a few at a time with it, rather than paging. The host is the button: it takes focus, and Enter and
// Space press it, as a <button> does.

/**
 * @summary The quiet "Show 5 more" under a list.
 * @slot - The words, in place of `label`.
 * @fires click - Pressed (pointer, Enter or Space).
 */
export class ShowMore extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { count: { type: Number }, label: {} }

	/** How many more it shows. */
	count = 5
	/** The words (else "Show <count> more"). */
	label?: string

	connectedCallback() {
		super.connectedCallback()
		if (!this.hasAttribute('role')) this.setAttribute('role', 'button')
		if (!this.hasAttribute('tabindex')) this.setAttribute('tabindex', '0')
		this.addEventListener('keydown', this.onKey)
	}
	disconnectedCallback() {
		super.disconnectedCallback()
		this.removeEventListener('keydown', this.onKey)
	}
	private onKey = (e: KeyboardEvent) => {
		if (e.key !== 'Enter' && e.key !== ' ') return
		e.preventDefault()
		this.click()
	}

	render() {
		return html`${this.hasSlot() ? html`<slot></slot>` : (this.label ?? `Show ${this.count} more`)}`
	}
}

define('show-more', ShowMore)

/* The host is the button (ShowMore.vue's root <button>, with role="button" and the keys a button has), so a class on
   <conare-show-more> (self-start) lands on it as on Vue's root. Its face is important: the page's reset and the scoped
   base layer (the type of a data-ds root) outrank :host, and Vue's classes win over them. */
:host { display: inline-block !important; position: relative !important; margin-left: calc(var(--spacing, 0.25rem) * 1) !important; cursor: pointer; font-size: var(--ds-text-meta) !important; line-height: var(--ds-text-meta-leading) !important; font-weight: var(--ds-font-weight-medium) !important; white-space: nowrap !important; color: var(--ds-color-fg-soft) !important; text-align: center; transition: color var(--ds-duration-micro) var(--ds-easing-standard); }
:host::after { position: absolute; inset: -12px; content: ""; }
@media (hover: hover) and (pointer: fine) { :host(:hover) { color: var(--ds-color-fg) !important; } }
:host(:focus-visible) { outline: var(--ds-border-focus) solid var(--ds-color-edge-accent) !important; outline-offset: var(--ds-border-focus) !important; }
